CREATE TABLE rs_user (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, username VARCHAR(40) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(10) NOT NULL CHECK (role IN ('STUDENT','ADMIN')), enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE rs_session (token_hash CHAR(64) PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES rs_user(id) ON DELETE CASCADE, expires_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX rs_session_user_idx ON rs_session(user_id);
